import { mkdir, readFile, writeFile } from 'node:fs/promises';
import * as path from 'node:path';

export const MANIFEST_REL_PATH = path.join('.archascode', 'manifest.json');

export interface Manifest {
  schemaVersion: 1;
  renderedAt: string;
  specPath: string;
  files: string[];
  /**
   * Paths the engine emitted under `once-ever` at least once — the
   * emit-once-ever tombstone. Separate from `files[]`, never read by
   * stale-cleanup. Once a path appears here, `writeFiles` skips it even
   * after it has been deleted from disk (making the delete stick).
   * `schemaVersion` stays `1` — this is an additive optional field, read
   * as `[]` when absent. See ADR 055 amendment A2.
   */
  seededOnceEver?: string[];
  /**
   * Schema state. Engine-known persistence adapters that need a cache
   * keyed off the spec (ADR 019).
   *
   * `sqlserver.inflightSlug` is the auto-inferred slug for the current
   * `_inflight.sql` content. It's the engine's view at render-time —
   * the `cut-schema-migration` verb reads it so it can produce a named
   * file without re-rendering. `null` when the spec produces no in-flight
   * delta; absent for projects without a SQL Server port binding.
   */
  schema?: {
    sqlserver?: {
      inflightSlug?: string | null;
    };
  };
  /**
   * Per-environment port binding + per-adapter env-scoped config (ADR 010).
   * Tooling (`aac up`, `/aac-up`) resolves the active environment from
   * this map; the rendered app itself only sees `APP_PORT_BINDING`. Absent
   * when the spec declares no `environments:` block.
   */
  environments?: Record<string, EnvironmentManifest>;
  /**
   * Name of the environment used by `aac up` / `/aac-up` when no
   * `--env` flag is passed. Must match a key in `environments`.
   */
  defaultEnvironment?: string;
}

export interface EnvironmentManifest {
  /** Port binding name (auto or user-declared) this environment selects. */
  portBinding: string;
  /**
   * ADR 017 — who owns the persistence infrastructure lifecycle.
   * `docker` means `aac up` runs docker compose. `external` means
   * something else owns the database. Absent for memory-only
   * environments (compute is not meaningful without persistence).
   */
  compute?: 'docker' | 'external';
  /**
   * ADR 017 — risk profile of the data. `ephemeral` keeps snapshot
   * endpoints and the ADR 016 lenient drift path enabled.
   * `protected` disables snapshot endpoints (rendered admin router
   * returns 403). Always present (defaults to `ephemeral`).
   */
  data: 'ephemeral' | 'protected';
  /**
   * Whether the chosen port binding routes any entity to the sqlserver
   * adapter. Engine-resolved (ADR 010 follow-on). Tooling (`aac up`,
   * `aac migrate`) branches on this — memory-only environments skip
   * compose/wait/apply.
   */
  needsSqlserver: boolean;
  /**
   * ADR 024 — per-environment resolved app-level adapter selections.
   * Today's only slot is `auth`. Tooling (`aac-apply`) reads this to
   * decide whether to dispatch the claims-mapper hand-off when
   * `auth.id === 'jwt_bearer'`. Absent on pre-ADR-024 manifests; the
   * apply skill falls back to `noop` when the field is missing.
   */
  appAdapters?: {
    auth?: { id: string };
  };
}

export async function readManifest(outDir: string): Promise<Manifest | null> {
  const manifestPath = path.join(outDir, MANIFEST_REL_PATH);
  let raw: string;
  try {
    raw = await readFile(manifestPath, 'utf8');
  } catch (err) {
    if (isNotFound(err)) return null;
    throw err;
  }
  const parsed = JSON.parse(raw) as Manifest;
  if (parsed.schemaVersion !== 1) {
    throw new Error(
      `unexpected manifest schemaVersion=${parsed.schemaVersion} at ${manifestPath}`,
    );
  }
  return parsed;
}

export async function writeManifest(outDir: string, manifest: Manifest): Promise<void> {
  const manifestPath = path.join(outDir, MANIFEST_REL_PATH);
  await mkdir(path.dirname(manifestPath), { recursive: true });
  await writeFile(manifestPath, JSON.stringify(manifest, null, 2) + '\n', 'utf8');
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}
