import { access, copyFile, mkdir, readFile } from 'node:fs/promises';
import * as path from 'node:path';

import type { HandoffItem } from 'archascode-protocol-ts';

import { assertSafeRelativePath } from './files';
import { STUB_MARKERS } from './handoffMarker';

export type PendingReason = 'no-overlay' | 'hash-drift' | 'stub-marker';

export interface PendingHandoff {
  item: HandoffItem;
  reason: PendingReason;
}

/**
 * Which overlay tree a body resolved from, or null if no body was found.
 * ADR 062 D1: the probe (not the impl_target_file hint) is the resolution authority.
 */
export type OverlayTree = 'locked' | 'src';

/**
 * Per-hand-off tree resolution information surfaced by the two-tree probe (ADR 062 D1).
 * Consumed by render.ts to perform the D8 reconciliation move (ADR 063 D1):
 *   hintTree = 'locked' but resolvedTree = 'src' → move spec/src/<rel> → spec/locked/<rel>.
 *   hintTree = 'src' but resolvedTree = 'locked' → move spec/locked/<rel> → spec/src/<rel>.
 * resolvedTree is null when no body exists in either tree ('no-overlay' reason).
 */
export interface HandoffTreeInfo {
  /** The tree the probe found the body in, or null if neither tree had it. */
  resolvedTree: OverlayTree | null;
  /** The tree the engine's impl_target_file hinted (derived from the path prefix). */
  hintTree: OverlayTree;
  /**
   * The tree-relative body path (the `impl_target_file` with its `spec/src/` or
   * `spec/locked/` prefix stripped) — surfaced so `render.ts` can build both absolute
   * move paths without re-deriving (ADR 063).
   */
  rel: string;
}

export interface ApplyOverlayResult {
  /** Hand-offs whose overlay existed and whose stored hash matched current. */
  resolved: HandoffItem[];
  /** Hand-offs left for the caller (apply skill) to dispatch — overlay missing, hash drifted, or stub-marker present. */
  pending: PendingHandoff[];
  /** New `contracts` map to persist in the interface lockfile. */
  contracts: Record<string, string>;
  /**
   * Per-hand-off tree resolution info (ADR 062 D1 + D8).
   * Keyed by item.id. Present for every item in the handoff list.
   * Consumed by render.ts to emit the D8 reconciliation warning.
   */
  treeInfo: Map<string, HandoffTreeInfo>;
}

/**
 * Derive the overlay-tree-relative path from an impl_target_file by stripping
 * the leading 'spec/locked/' or 'spec/src/' prefix. Returns { rel, hintTree }.
 * The hintTree is 'locked' if the path starts with 'spec/locked/', else 'src'.
 * ADR 062 D1: the engine's impl_target_file is a seed-destination + default hint,
 * not the resolution authority — the probe (not this value) decides which tree wins.
 */
function stripOverlayTreePrefix(implTargetFile: string): { rel: string; hintTree: OverlayTree } {
  const LOCKED_PREFIX = 'spec/locked/';
  const SRC_PREFIX = 'spec/src/';
  if (implTargetFile.startsWith(LOCKED_PREFIX)) {
    return { rel: implTargetFile.slice(LOCKED_PREFIX.length), hintTree: 'locked' };
  }
  if (implTargetFile.startsWith(SRC_PREFIX)) {
    return { rel: implTargetFile.slice(SRC_PREFIX.length), hintTree: 'src' };
  }
  // Fallback: treat the whole path as rel, hint src. Handles any unexpected form
  // gracefully (the assertSafeRelativePath guard above catches traversal attempts).
  return { rel: implTargetFile, hintTree: 'src' };
}

/**
 * Probe spec/locked/<rel> first, then spec/src/<rel> as fallback.
 * Returns { overlayAbs, resolvedTree } — overlayAbs is the resolved path (may
 * not exist if neither tree has the body), resolvedTree is which tree had it.
 * ADR 062 D1: locked/ wins when both trees have the body.
 */
async function probeOverlayTree(
  outDir: string,
  rel: string,
): Promise<{ overlayAbs: string; resolvedTree: OverlayTree | null }> {
  const lockedAbs = path.join(outDir, 'spec', 'locked', rel);
  if (await pathExists(lockedAbs)) {
    return { overlayAbs: lockedAbs, resolvedTree: 'locked' };
  }
  const srcAbs = path.join(outDir, 'spec', 'src', rel);
  if (await pathExists(srcAbs)) {
    return { overlayAbs: srcAbs, resolvedTree: 'src' };
  }
  // Neither tree has the body — return the src path for downstream use (it won't
  // exist, so pathExists checks that follow will report false correctly).
  return { overlayAbs: srcAbs, resolvedTree: null };
}

/**
 * For each `HandoffItem`, if the overlay file exists *and* the stored hash
 * matches the current contract hash, copy the overlay over the engine-emitted
 * shell at `contract_file`. Otherwise leave the shell in place (the
 * engine's stub stays runnable for non-extension callers) and surface the
 * item as pending.
 *
 * ADR 062 D1: the overlay is resolved by a two-tree probe — spec/locked/<rel>
 * first, spec/src/<rel> as fallback. The engine's impl_target_file is a hint
 * (seed destination), not the resolution authority. This makes a late
 * 'locked: true' flag flip or a git mv safe — the probe finds the body wherever
 * it physically lives.
 *
 * Stateless w.r.t. agent orchestration — the apply-skill above decides what
 * to do with pending items. This keeps core trivially callable from CLI and
 * plugin contexts.
 */
export async function applyOverlay(
  outDir: string,
  handoff: readonly HandoffItem[],
  previousContracts: Readonly<Record<string, string>> | undefined,
): Promise<ApplyOverlayResult> {
  const resolved: HandoffItem[] = [];
  const pending: PendingHandoff[] = [];
  const contracts: Record<string, string> = { ...(previousContracts ?? {}) };
  const treeInfo = new Map<string, HandoffTreeInfo>();

  for (const item of handoff) {
    assertSafeRelativePath(item.impl_target_file);
    assertSafeRelativePath(item.contract_file);

    // ADR 062 D1: derive rel + hintTree from impl_target_file, then probe both
    // trees — spec/locked/<rel> first, spec/src/<rel> as fallback.
    const { rel, hintTree } = stripOverlayTreePrefix(item.impl_target_file);
    const { overlayAbs, resolvedTree } = await probeOverlayTree(outDir, rel);

    const targetAbs = path.join(outDir, item.contract_file);
    const stored = contracts[item.id];
    const overlayExists = resolvedTree !== null;

    // Record tree info for every item (consumed by render.ts for D8 reconciliation, ADR 063).
    treeInfo.set(item.id, { resolvedTree, hintTree, rel });

    if (stored === item.contract_hash && overlayExists) {
      const overlayText = await readFile(overlayAbs, 'utf8');
      if (STUB_MARKERS.some((m) => overlayText.includes(m))) {
        // ADR 040 #1/#3 / ADR 042 #3: a resolved hand-off must not ship a stub.
        // The overlay still carries a seed marker → pending, regardless of
        // hash-match. Checks STUB_MARKERS (entity_method + custom_port_adapter)
        // so any per-method stub marker is caught — a partially-filled custom-port
        // adapter (one method done, one still stubbed) stays pending as required
        // (ADR 042 #3: any marker present ⇒ pending). The delete is REQUIRED, not
        // optional cleanup: the recorded hash is written out-of-band by
        // recordHandoffResolution (render.ts), so leaving contracts[id] standing
        // for a marker-bearing overlay would persist the exact
        // recorded-resolved-but-stubbed lie these ADRs kill.
        // Kind-agnostic on purpose — fires for any overlay carrying any known
        // marker literal; no `item.kind` branch.
        delete contracts[item.id];
        pending.push({ item, reason: 'stub-marker' });
        continue;
      }
      await mkdir(path.dirname(targetAbs), { recursive: true });
      await copyFile(overlayAbs, targetAbs);
      contracts[item.id] = item.contract_hash;
      resolved.push(item);
    } else {
      // Hash mismatch (or overlay absent) invalidates the cached resolution so
      // a stale hash can't survive a contract change.
      // Attribute the reason:
      //   'no-overlay'   — the file is absent (path does not exist in either tree).
      //   'stub-marker'  — the file exists but carries a stub marker AND the
      //                    hash didn't match (includes stored === undefined, which
      //                    is the "no prior contract" case). Without this check a
      //                    legitimately-unimplemented overlay that has no prior
      //                    lockfile entry would get 'hash-drift' and trigger a
      //                    spurious overlay-without-entry warning in render().
      //   'hash-drift'   — the file exists, is stub-free, but the stored/absent
      //                    hash didn't match. This is the "copied bodies, lost
      //                    ledger" signature that Decision 4 warns on.
      delete contracts[item.id];
      let reason: PendingReason;
      if (!overlayExists) {
        reason = 'no-overlay';
      } else {
        const overlayText = await readFile(overlayAbs, 'utf8');
        reason = STUB_MARKERS.some((m) => overlayText.includes(m)) ? 'stub-marker' : 'hash-drift';
      }
      pending.push({ item, reason });
    }
  }

  return { resolved, pending, contracts, treeInfo };
}

async function pathExists(p: string): Promise<boolean> {
  try {
    await access(p);
    return true;
  } catch {
    return false;
  }
}
