import { realpathSync } from 'node:fs';
import { access } from 'node:fs/promises';
import { createInterface } from 'node:readline/promises';
import { pathToFileURL } from 'node:url';
import { parseArgs } from 'node:util';

import {
  CloudRequestError,
  cleanProject,
  cutSchemaMigration,
  getAuthToken,
  isLocalDevOrigin,
  login,
  logout,
  planClean,
  readCredentials,
  recordHandoffResolution,
  render,
  resolveCloudUrl,
} from 'archascode-core';

import { runClean as runCleanCore } from './clean';
import { defaultInvokeMigrate, runDeploy } from './deploy';

const DEFAULT_SPEC_PATH = './spec/architecture.yml';

const USAGE = `archascode — local CLI

Usage:
  archascode render [<spec-path>] [--out <dir>] [--cloud-url <url>] [--json]
  archascode login [--cloud-url <url>] [--username <name>]
  archascode logout
  archascode record-handoff --id <handoff-id> --hash <contract-hash> [--out <dir>]
  archascode cut-schema-migration [--name <slug>] [--out <dir>] [--json]
  archascode db plan  --env <name> [--out <dir>] [--plan-out <file>] [--up-to <bound>]
  archascode db apply --env <name> [--out <dir>] [--baseline-existing-target] [--up-to <bound>]
  archascode clean [--out <dir>] [--yes] [--json] [--hard]

Arguments:
  <spec-path>         Path to architecture.yml (default ${DEFAULT_SPEC_PATH})

Options:
  --out <dir>         Output directory (default \`.\`, the current working
                      directory). Rendered files land at the project root
                      alongside spec/, so aac.py and the dual-tree layout
                      (src/, spec/src/) sit where downstream tooling expects.
                      Run from a git tree so accidental overwrites can be
                      rolled back.
  --cloud-url <url>   archascode cloud base URL. Resolved by precedence:
                      this flag > $ARCHASCODE_DEV_CLOUD_URL > the
                      credentials-file cloudUrl (written by
                      \`archascode login\`). When none is set, render fails:
                      not logged in (run \`archascode login\`). Internal dev:
                      export ARCHASCODE_DEV_CLOUD_URL to target a
                      local/alternate cloud service.
  --username <name>   Username for \`archascode login\` (prompted if omitted).
  --json              Emit a machine-readable summary on stdout.
                      render schema:  { ok, filesWritten, filesRemoved,
                                        handoff: { resolved, pending } } |
                                      { ok: false, errors }.
                      cut-schema-migration schema:
                                      { ok: true, producedFilename } |
                                      { ok: false, reason, message }.
                      clean schema:   { ok: true, removed, warnings } |
                                      { ok: false, reason: "aborted" }.
  --id <handoff-id>   HandoffItem.id to record (record-handoff).
  --hash <hash>       Contract hash to persist (record-handoff).
  --name <slug>       Override the auto-inferred slug for the cut migration
                      file. Normalized to lowercase snake_case.
  --env <name>        Environment name (from architecture.yml) to target.
                      Required for db plan and db apply.
  --plan-out <file>   Preview destination for \`db plan\` (default stdout).
                      Distinct from the global --out <dir> (render root).
                      When set, stdout carries only a one-line summary pointer
                      and the file carries the SQL plan script.
  --baseline-existing-target
                      One-shot: record cuts on disk as applied in
                      schema_version *without* running their DDL. For
                      protected targets that pre-date ADR 021. Use once
                      per target, then drop the flag. (db apply and db plan)
  --up-to <bound>     Bound the pending cut selection to versions <= bound
                      (inclusive). Accepts a 1-14 digit version prefix
                      (right-padded with 9s to 14 digits, so --up-to 20260701
                      means "through the end of July 1") or a full cut
                      filename (20260701123045_add_x.sql, with or without the
                      .sql extension). The divergence checks still run
                      against the full disk cut set; the bound only narrows
                      the unapplied selection. Cannot be combined with
                      --baseline-existing-target (bounded baselining is
                      deferred; see ADR 069). (db apply and db plan)
  -y, --yes           Skip the confirmation prompt (clean). For scripted
                      and skill-driven use.
  -h, --help          Show this message

login / logout — archascode cloud accounts are invite-only: an operator
           creates your user via \`admin-create-user\`, and your first login
           asks you to choose a new password (Cognito's NEW_PASSWORD_REQUIRED
           challenge). \`login\` prompts for username/password (or takes
           --username) and caches tokens + the cloud URL at
           ~/.archascode/credentials.json (mode 0600). \`logout\` deletes that
           file. Requires a TTY; there is no non-interactive form (no
           --password flag — passwords are never accepted on the command
           line).

db plan  — read-only preview: connects to the target, computes the true
           pending cut set, runs divergence checks, and emits the exact SQL
           db apply would execute. Applies nothing. Refuses on divergence
           identically to db apply. Output goes to stdout by default.

db apply — execute verb (formerly \`archascode deploy\`): behaviorally
           identical to the old deploy command in every respect.

clean (default): resets the regenerable surface (src/, aac.py,
docker-compose.yml, .archascode/manifest.json, and spec/src/ wholesale).
Preserves spec/locked/ (hand-authored bodies + sealed migrations + the
interfaces.lock ledger). Safe to run without losing irreplaceable work;
git can recover the deleted regenerable content.

clean --hard: total reset — deletes everything incl. spec/locked/ and
sealed migrations, leaving only spec/architecture.yml and positions.json.
Use only to rebuild from zero (e.g. a corrupted migration chain).
Destructive and named explicitly; no short alias.
`;

export async function main(argv: readonly string[]): Promise<number> {
  let parsed;
  try {
    parsed = parseArgs({
      args: [...argv],
      options: {
        out: { type: 'string', default: '.' },
        'cloud-url': { type: 'string' },
        username: { type: 'string' },
        json: { type: 'boolean', default: false },
        id: { type: 'string' },
        hash: { type: 'string' },
        name: { type: 'string' },
        env: { type: 'string' },
        'plan-out': { type: 'string' },
        'baseline-existing-target': { type: 'boolean', default: false },
        'up-to': { type: 'string' },
        yes: { type: 'boolean', short: 'y', default: false },
        hard: { type: 'boolean', default: false },
        help: { type: 'boolean', short: 'h', default: false },
      },
      allowPositionals: true,
    });
  } catch (err) {
    process.stderr.write(`error: ${(err as Error).message}\n\n${USAGE}`);
    return 2;
  }

  const { values, positionals } = parsed;

  if (values.help) {
    process.stdout.write(USAGE);
    return 0;
  }

  const [command, ...rest] = positionals;
  if (!command) {
    process.stderr.write(USAGE);
    return 2;
  }

  if (command === 'render') {
    return await runRender(values, rest);
  }

  if (command === 'login') {
    return await runLogin(values, defaultAuthCliDeps());
  }

  if (command === 'logout') {
    return await runLogout(values, defaultAuthCliDeps());
  }

  if (command === 'record-handoff') {
    return await runRecordHandoff(values);
  }

  if (command === 'cut-schema-migration') {
    return await runCutSchemaMigration(values);
  }

  if (command === 'db') {
    return await runDbCmd(rest, values);
  }

  if (command === 'clean') {
    return await runClean(values);
  }

  process.stderr.write(`unknown command: ${command}\n\n${USAGE}`);
  return 2;
}

async function runRender(
  values: Record<string, unknown>,
  rest: string[],
): Promise<number> {
  const specPath = rest[0] ?? DEFAULT_SPEC_PATH;
  const usedDefault = rest[0] === undefined;

  try {
    await access(specPath);
  } catch {
    process.stderr.write(
      usedDefault
        ? `render: no spec at default path ${DEFAULT_SPEC_PATH}; pass an explicit <spec-path>\n\n${USAGE}`
        : `render: spec not found at ${specPath}\n`,
    );
    return 2;
  }

  const outDir = values.out as string;
  const wantJson = Boolean(values.json);

  const creds = await readCredentials();
  const cloudUrl = resolveCloudUrl({
    explicit: values['cloud-url'] as string | undefined,
    env: process.env.ARCHASCODE_DEV_CLOUD_URL,
    credentials: creds?.cloudUrl,
  });
  if (cloudUrl === null) {
    process.stderr.write(
      'render failed: not logged in to archascode\nhint: run `archascode login`\n',
    );
    return 2;
  }
  const authToken = isLocalDevOrigin(cloudUrl)
    ? undefined
    : ((await getAuthToken()) ?? undefined);

  if (!wantJson) {
    process.stderr.write(`rendering ${specPath} → ${outDir}\n`);
  }

  let outcome;
  try {
    outcome = await render({
      specPath,
      outDir,
      cloudUrl,
      ...(authToken !== undefined ? { authToken } : {}),
    });
  } catch (err) {
    let msg = `render failed: ${(err as Error).message}`;
    if (err instanceof CloudRequestError && err.status === 401) {
      msg += '\nhint: run `archascode login`';
    }
    if (wantJson) {
      process.stdout.write(
        JSON.stringify({ ok: false, errors: [msg] }) + '\n',
      );
    } else {
      process.stderr.write(`${msg}\n`);
    }
    return 1;
  }

  if (wantJson) {
    process.stdout.write(JSON.stringify(outcome) + '\n');
    return outcome.ok ? 0 : 1;
  }

  if (!outcome.ok) {
    process.stderr.write('spec rejected by cloud:\n');
    for (const e of outcome.errors) {
      process.stderr.write(`  - ${e}\n`);
    }
    return 1;
  }

  process.stdout.write(
    `wrote ${outcome.filesWritten.length} file(s) to ${outDir}` +
      (outcome.filesRemoved.length > 0
        ? ` (removed ${outcome.filesRemoved.length} stale)`
        : '') +
      (outcome.handoff.pending.length > 0
        ? ` (${outcome.handoff.pending.length} pending hand-off${outcome.handoff.pending.length === 1 ? '' : 's'})`
        : '') +
      '\n',
  );
  // Print consistency warnings to stderr (Decision 4, ADR 054).
  // The --json path already serializes the whole outcome (including the warnings
  // field) — only the non-JSON path needs an explicit print.
  if (outcome.warnings) {
    for (const w of outcome.warnings) {
      process.stderr.write(`${w}\n`);
    }
  }
  return 0;
}

/**
 * Reads one line from a raw-mode TTY, echoing '*' per character instead of
 * the real input. Backspace/Delete erase the last '*'; Enter finishes;
 * Ctrl-C aborts the process (raw mode disables the shell's own SIGINT echo).
 */
function promptMasked(question: string): Promise<string> {
  return new Promise((resolve) => {
    const { stdin, stderr } = process;
    stderr.write(question);
    let answer = '';
    stdin.setRawMode(true);
    stdin.resume();
    stdin.setEncoding('utf8');
    const onData = (chunk: string) => {
      for (const char of chunk) {
        if (char === '\r' || char === '\n') {
          cleanup();
          stderr.write('\n');
          resolve(answer.trim());
          return;
        } else if (char === '\x03') {
          cleanup();
          stderr.write('\n');
          process.exit(130);
        } else if (char === '\x7f' || char === '\b') {
          if (answer.length > 0) {
            answer = answer.slice(0, -1);
            stderr.write('\b \b');
          }
        } else if (char >= ' ') {
          answer += char;
          stderr.write('*');
        }
      }
    };
    const cleanup = () => {
      stdin.off('data', onData);
      stdin.setRawMode(false);
      stdin.pause();
    };
    stdin.on('data', onData);
  });
}

/**
 * IO/auth surface for `login`/`logout`, injectable so tests drive prompts
 * without a real TTY and without touching ~/.archascode/credentials.json
 * (ADR-071 Fork F8; mirrors `CleanIO`'s injection shape).
 */
export interface AuthCliDeps {
  prompt: (q: string) => Promise<string>;
  promptSecret: (q: string) => Promise<string>;
  login: typeof login;
  logout: typeof logout;
  isTTY: () => boolean;
}

function defaultAuthCliDeps(): AuthCliDeps {
  return {
    prompt: async (q: string) => {
      const rl = createInterface({ input: process.stdin, output: process.stderr });
      try {
        return (await rl.question(q)).trim();
      } finally {
        rl.close();
      }
    },
    promptSecret: async (q: string) => {
      // readline's question() only yields the final line, so it can't echo a
      // '*' per keystroke — that needs raw-mode keypress reading instead.
      // Best-effort: non-TTY streams (piped input) have no raw mode, so they
      // fall back to a plain (unmasked) line read.
      if (!process.stdin.isTTY) {
        const rl = createInterface({ input: process.stdin, output: process.stderr });
        try {
          return (await rl.question(q)).trim();
        } finally {
          rl.close();
        }
      }
      return promptMasked(q);
    },
    login,
    logout,
    isTTY: () => process.stdin.isTTY === true,
  };
}

export async function runLogin(
  values: Record<string, unknown>,
  deps: AuthCliDeps,
): Promise<number> {
  const explicitUsername = values.username as string | undefined;

  // A prompt is always needed for the password (never a --password flag —
  // shell-history leak) and for the username when --username is absent.
  if (!deps.isTTY()) {
    process.stderr.write('login: no TTY for prompts\n');
    return 2;
  }

  const username = explicitUsername ?? (await deps.prompt('Username: '));
  const password = await deps.promptSecret('Password: ');
  const explicitCloudUrl = values['cloud-url'] as string | undefined;

  try {
    const creds = await deps.login({
      username,
      password,
      promptNewPassword: () =>
        deps.promptSecret('New password required — choose one: '),
      ...(explicitCloudUrl !== undefined ? { cloudUrl: explicitCloudUrl } : {}),
    });
    process.stdout.write(`logged in as ${creds.username} (${creds.cloudUrl})\n`);
    return 0;
  } catch (err) {
    process.stderr.write(`login failed: ${(err as Error).message}\n`);
    return 1;
  }
}

export async function runLogout(
  _values: Record<string, unknown>,
  deps: AuthCliDeps,
): Promise<number> {
  const removed = await deps.logout();
  process.stdout.write(removed ? 'logged out\n' : 'no credentials to remove\n');
  return 0;
}

async function runRecordHandoff(values: Record<string, unknown>): Promise<number> {
  const id = values.id as string | undefined;
  const hash = values.hash as string | undefined;
  const outDir = values.out as string;
  if (!id || !hash) {
    process.stderr.write(
      'record-handoff: --id and --hash are required\n\n' + USAGE,
    );
    return 2;
  }
  try {
    await recordHandoffResolution(outDir, id, hash);
  } catch (err) {
    process.stderr.write(`record-handoff failed: ${(err as Error).message}\n`);
    return 1;
  }
  process.stdout.write(`recorded ${id}=${hash} in ${outDir}\n`);
  return 0;
}

async function runCutSchemaMigration(
  values: Record<string, unknown>,
): Promise<number> {
  const outDir = values.out as string;
  const name = (values.name as string | undefined) ?? undefined;
  const wantJson = Boolean(values.json);

  let outcome;
  try {
    outcome = await cutSchemaMigration({ outDir, name });
  } catch (err) {
    const msg = `cut-schema-migration failed: ${(err as Error).message}`;
    if (wantJson) {
      process.stdout.write(
        JSON.stringify({ ok: false, reason: 'error', message: msg }) + '\n',
      );
    } else {
      process.stderr.write(`${msg}\n`);
    }
    return 1;
  }

  if (wantJson) {
    process.stdout.write(JSON.stringify(outcome) + '\n');
    return outcome.ok ? 0 : 3;
  }

  if (!outcome.ok) {
    process.stderr.write(`${outcome.message}\n`);
    return 3;
  }

  process.stdout.write(`cut migration ${outcome.producedFilename}\n`);
  return 0;
}

async function runClean(values: Record<string, unknown>): Promise<number> {
  const outDir = values.out as string;
  const assumeYes = Boolean(values.yes);
  const wantJson = Boolean(values.json);
  const hard = Boolean(values.hard);

  const outcome = await runCleanCore(
    { outDir, assumeYes, json: wantJson, hard },
    {
      stdout: (text) => process.stdout.write(text),
      stderr: (text) => process.stderr.write(text),
      confirm: async (prompt) => {
        // No TTY (piped/CI) and no --yes: refuse rather than block on a
        // prompt that can never be answered. The user can re-run with --yes.
        if (!process.stdin.isTTY) {
          process.stderr.write(
            'clean: no TTY for confirmation; re-run with --yes to proceed.\n',
          );
          return false;
        }
        const rl = createInterface({
          input: process.stdin,
          output: process.stderr,
        });
        try {
          const answer = (await rl.question(prompt)).trim().toLowerCase();
          return answer === 'y' || answer === 'yes';
        } finally {
          rl.close();
        }
      },
    },
  );

  // Aborting is a user choice, not a failure (human mode → exit 0). In
  // --json mode, surface the abort as a non-zero code so scripts branch.
  if (!outcome.ok) {
    return wantJson ? 3 : 0;
  }
  return 0;
}

/** Shape a `--up-to <bound>` raw value can take, per ADR 069 Decision 2. */
const UP_TO_DIGITS_RE = /^\d{1,14}$/;
const UP_TO_FILENAME_RE = /^(\d{14})_[a-z0-9_]+(\.sql)?$/;

export type ParseUpToBoundResult =
  | { ok: true; upTo: string }
  | { ok: false; message: string };

/**
 * Validates and normalizes a raw `--up-to` value (ADR 069, Fork F6).
 *
 * Accepts either a 1-14 digit version prefix, or a full cut filename
 * (`<14-digit-timestamp>_<slug>.sql`, with or without the `.sql`
 * extension) — the copy-paste form — from which the leading 14 digits are
 * extracted. Everything else, including the empty string, is rejected with
 * a message naming the raw value and the two accepted forms. Does NOT pad
 * the result — padding to 14 digits is the rendered module's job
 * (`_normalize_up_to`), not the CLI's.
 */
export function parseUpToBound(raw: string): ParseUpToBoundResult {
  if (UP_TO_DIGITS_RE.test(raw)) {
    return { ok: true, upTo: raw };
  }
  const filenameMatch = UP_TO_FILENAME_RE.exec(raw);
  if (filenameMatch) {
    return { ok: true, upTo: filenameMatch[1]! };
  }
  return {
    ok: false,
    message:
      `invalid --up-to value ${JSON.stringify(raw)}: expected a 1-14 digit ` +
      `version prefix (e.g. 20260701) or a full cut filename ` +
      `(<14-digit-timestamp>_<slug>.sql)`,
  };
}

async function runDbCmd(
  rest: string[],
  values: Record<string, unknown>,
): Promise<number> {
  const subverb = rest[0];
  if (subverb === 'apply') {
    return await runDbApplyCmd(values);
  }
  if (subverb === 'plan') {
    return await runDbPlanCmd(values);
  }
  const verbDisplay = subverb ? `unknown db verb: ${subverb}` : 'db: missing subverb';
  process.stderr.write(`${verbDisplay}\n\n${USAGE}`);
  return 2;
}

/**
 * Validates a raw `--up-to` value shared by both db verbs (ADR 069, Fork
 * F8). Order is load-bearing: the --baseline-existing-target combination
 * is rejected before shape validation, so a user attempting bounded
 * adoption with a typo'd bound hears about the deferral (the
 * decision-relevant message) rather than the typo. Returns the extracted
 * digit string on success, or writes the error + USAGE and returns null on
 * failure (caller returns 2).
 */
function resolveUpTo(
  verbLabel: string,
  values: Record<string, unknown>,
): string | undefined | null {
  const rawUpTo = values['up-to'] as string | undefined;
  if (rawUpTo === undefined) {
    return undefined;
  }
  const baselineExisting = Boolean(values['baseline-existing-target']);
  if (baselineExisting) {
    process.stderr.write(
      `${verbLabel}: --up-to cannot be combined with --baseline-existing-target ` +
        `(bounded baselining is deferred; see ADR 069)\n\n${USAGE}`,
    );
    return null;
  }
  const result = parseUpToBound(rawUpTo);
  if (!result.ok) {
    process.stderr.write(`${verbLabel}: ${result.message}\n\n${USAGE}`);
    return null;
  }
  return result.upTo;
}

async function runDbApplyCmd(values: Record<string, unknown>): Promise<number> {
  const outDir = values.out as string;
  const envName = values.env as string | undefined;
  const baselineExisting = Boolean(values['baseline-existing-target']);
  if (!envName) {
    process.stderr.write('db apply: --env <name> is required\n\n' + USAGE);
    return 2;
  }
  const upTo = resolveUpTo('db apply', values);
  if (upTo === null) {
    return 2;
  }
  return await runDeploy(
    { outDir, envName, baselineExisting, mode: 'apply', upTo },
    {
      stderr: (text) => process.stderr.write(text),
      invokeMigrate: defaultInvokeMigrate,
    },
  );
}

async function runDbPlanCmd(values: Record<string, unknown>): Promise<number> {
  const outDir = values.out as string;
  const envName = values.env as string | undefined;
  const planOut = values['plan-out'] as string | undefined;
  if (!envName) {
    process.stderr.write('db plan: --env <name> is required\n\n' + USAGE);
    return 2;
  }
  const baselineExisting = Boolean(values['baseline-existing-target']);
  const upTo = resolveUpTo('db plan', values);
  if (upTo === null) {
    return 2;
  }
  return await runDeploy(
    { outDir, envName, baselineExisting, mode: 'plan', planOut, upTo },
    {
      stderr: (text) => process.stderr.write(text),
      invokeMigrate: defaultInvokeMigrate,
    },
  );
}

// Module entrypoint: only invoke `main` when this file is the process
// entry. Importing the module (for tests) doesn't run the CLI. argv[1] is
// realpath'd because npm-installed bin entries are symlinks to the bundle —
// comparing the symlink path against import.meta.url would silently exit 0.
const isEntry = (() => {
  if (typeof process.argv[1] !== 'string') return false;
  try {
    return import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href;
  } catch {
    return false;
  }
})();

if (isEntry) {
  main(process.argv.slice(2))
    .then((code) => process.exit(code))
    .catch((err) => {
      process.stderr.write(`unexpected: ${(err as Error).stack ?? err}\n`);
      process.exit(1);
    });
}
