import { mkdir, readdir, rename, rm, stat } from 'node:fs/promises';
import * as path from 'node:path';

import { assertSafeRelativePath } from './files';
import type { HandoffTreeInfo } from './handoff';

/**
 * Prune empty directories under `root` (bottom-up post-order traversal).
 * Does not remove `root` itself.
 *
 * Semantics (contract-load-bearing — ADR 063 Contract #3c / ADR 063 D1):
 *   - A directory is removed ONLY when it has zero remaining entries
 *     (strictly zero-entry, never ancestor-walking rmdir -p).
 *   - A package dir shared by a still-present sibling body is non-empty
 *     after the move, so the prune correctly leaves it — zero-entry is the
 *     invariant that makes locking one sibling safe for derived siblings.
 *   - Root itself is never removed (leaves an empty spec/src/ or spec/locked/
 *     harmless — the next render re-seeds markers into it).
 *
 * Extracted from cleanProject.ts (behavior-preserving — cleanProject.test.ts
 * stays green untouched; ADR-063 OQ-1 resolved: extract, one copy, one place).
 */
export async function pruneEmptyDirs(root: string): Promise<void> {
  let entries: string[];
  try {
    entries = await readdir(root);
  } catch (err) {
    if (isNotFound(err)) return;
    throw err;
  }

  for (const name of entries) {
    const abs = path.join(root, name);
    let isDir: boolean;
    try {
      const s = await stat(abs);
      isDir = s.isDirectory();
    } catch (err) {
      if (isNotFound(err)) continue;
      throw err;
    }
    if (!isDir) continue;

    // Recurse first (post-order).
    await pruneEmptyDirs(abs);

    // Now try to remove the directory if empty.
    const remaining = await readdir(abs).catch((e: unknown) => {
      if (isNotFound(e)) return [];
      throw e;
    });
    if (remaining.length === 0) {
      await rm(abs, { recursive: true, force: true });
    }
  }
}

/**
 * Reconcile the overlay tree to match the `locked` flag at local render.
 *
 * For each hand-off in `treeInfo`, if the body's physical tree disagrees with
 * its spec-declared intent (hintTree), core moves the body to the correct tree.
 *
 * Directions (ADR 063 D1):
 *   - lock   (hintTree === 'locked' && resolvedTree === 'src'):
 *       move spec/src/<rel> → spec/locked/<rel>, prune empty spec/src/ dirs.
 *   - un-lock (hintTree === 'src' && resolvedTree === 'locked'):
 *       move spec/locked/<rel> → spec/src/<rel>, prune empty spec/locked/ dirs.
 *   - else (hintTree === resolvedTree, steady state — incl. resolvedTree === null):
 *       no move, no report.
 *
 * The resolvedTree === null missing-body case is NOT handled here — it stays a
 * warning in render.ts (OQ-3: helper is a pure mover, never a "couldn't move" warner).
 *
 * The move is a plain fs.rename (D2 — no git mv, no git command). The two trees
 * are sibling dirs under outDir/spec/, so they are on the SAME filesystem by
 * construction — no EXDEV copy-then-unlink fallback is needed or added.
 *
 * @returns A list of human-readable move-report messages (the caller appends
 * them to `warnings` on the existing `RenderOutcome.warnings` channel — ADR 063 D3).
 */
export async function reconcileOverlayTree(
  outDir: string,
  treeInfo: ReadonlyMap<string, HandoffTreeInfo>,
): Promise<string[]> {
  const reports: string[] = [];

  for (const [id, info] of treeInfo) {
    if (info.hintTree === 'locked' && info.resolvedTree === 'src') {
      // Lock direction: move spec/src/<rel> → spec/locked/<rel>
      assertSafeRelativePath(info.rel); // defense-in-depth
      const srcAbs = path.join(outDir, 'spec', 'src', info.rel);
      const destAbs = path.join(outDir, 'spec', 'locked', info.rel);
      await mkdir(path.dirname(destAbs), { recursive: true });
      await rename(srcAbs, destAbs);
      // Prune now-empty dirs under spec/src/ (zero-entry, post-order — never ancestor-walking)
      await pruneEmptyDirs(path.join(outDir, 'spec', 'src'));
      reports.push(
        `moved body for hand-off \`${id}\` from spec/src/ → spec/locked/ to honor \`locked: true\``,
      );
    } else if (info.hintTree === 'src' && info.resolvedTree === 'locked') {
      // Un-lock direction: move spec/locked/<rel> → spec/src/<rel>
      assertSafeRelativePath(info.rel); // defense-in-depth
      const srcAbs = path.join(outDir, 'spec', 'locked', info.rel);
      const destAbs = path.join(outDir, 'spec', 'src', info.rel);
      await mkdir(path.dirname(destAbs), { recursive: true });
      await rename(srcAbs, destAbs);
      // Prune now-empty dirs under spec/locked/ (zero-entry, post-order — never ancestor-walking)
      await pruneEmptyDirs(path.join(outDir, 'spec', 'locked'));
      reports.push(
        `moved body for hand-off \`${id}\` from spec/locked/ → spec/src/ — \`locked\` is no longer declared`,
      );
    }
    // else: hintTree === resolvedTree (steady state) or resolvedTree === null (missing body)
    // — no move, no report (the missing-body case is handled in render.ts, not here)
  }

  return reports;
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}
