import { readFile, readdir } from 'node:fs/promises';
import * as path from 'node:path';

import type {
  EnvironmentManifestEntry,
  HandoffItem,
  PriorMigrationFile,
} from 'archascode-protocol-ts';

import { type Fetcher, postRender } from './client';
import { deleteFiles, writeFiles } from './files';
import { applyOverlay } from './handoff';
import { readInterfaceLock, writeInterfaceLock } from './interfaceLock';
import { type EnvironmentManifest, readManifest, writeManifest } from './manifest';
import { reconcileOverlayTree } from './overlayMove';

export interface RenderOptions {
  /** Absolute or cwd-relative path to an `architecture.yml` file. */
  specPath: string;
  /** Directory where generated files are written. Created if absent. */
  outDir: string;
  /** Base URL of the archascode cloud service (e.g. `http://localhost:8100`). */
  cloudUrl: string;
  /** Override `fetch` (for tests). */
  fetcher?: Fetcher;
  /** Override the wall clock (for tests). */
  now?: () => Date;
  /** Bearer token attached to the cloud request when provided (ADR 071). */
  authToken?: string;
}

export interface RenderHandoffOutcome {
  resolved: HandoffItem[];
  pending: HandoffItem[];
}

export type RenderOutcome =
  | {
      ok: true;
      filesWritten: string[];
      filesRemoved: string[];
      handoff: RenderHandoffOutcome;
      /** Non-fatal consistency warnings from the Decision 4 (ADR 054) check.
       * Omitted when there are no warnings (field absent, not empty array).
       * Populated when overlay-without-entry or entry-without-overlay is detected. */
      warnings?: string[];
    }
  | { ok: false; errors: string[] };

const SPEC_MIGRATIONS_REL_DIR = path.join(
  'spec',
  'locked',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
);
const INFLIGHT_FILENAME = '_inflight.sql';

export async function render(opts: RenderOptions): Promise<RenderOutcome> {
  const specYaml = await readFile(opts.specPath, 'utf8');

  const previous = await readManifest(opts.outDir);

  const priorMigrations = await readPriorMigrations(opts.outDir);

  const response = await postRender(
    opts.cloudUrl,
    {
      spec_yaml: specYaml,
      prior_migrations: priorMigrations,
    },
    opts.fetcher,
    opts.authToken,
  );

  if (response.errors.length > 0) {
    return { ok: false, errors: response.errors };
  }

  // Manifest only tracks always-overwrite files. Once-policy and once-ever-policy
  // files are deliberately excluded so the engine never deletes the agent's
  // working copy or the user's kept examples.
  //
  // The filter uses an ALLOWLIST (f.policy === 'overwrite') rather than a
  // denylist form — this makes every unrecognized future policy fail-safe
  // (untracked) rather than accidentally becoming stale-deletable. See ADR 055
  // amendment A2/A5.
  //
  // ADR 020 / ADR 066: cut projections under src/.../migrations/ are tracked
  // overwrite files like any other engine output. A cut deleted from
  // spec/locked/ stops being projected, falls out of trackedPathSet, and
  // gets cleanly removed by stale-cleanup — which is the correct undo.
  const trackedPaths = response.files
    .filter((f) => (f.policy ?? 'overwrite') === 'overwrite')
    .map((f) => f.path);
  const trackedPathSet = new Set(trackedPaths);
  const stalePaths = (previous?.files ?? []).filter(
    (p) => !trackedPathSet.has(p),
  );

  // Read the prior tombstone so writeFiles can skip already-tombstoned once-ever files.
  const priorTombstone = new Set(previous?.seededOnceEver ?? []);

  const { writtenPaths, seededOnceEverPaths } = await writeFiles(opts.outDir, response.files, priorTombstone);
  await deleteFiles(opts.outDir, stalePaths);

  const handoffItems = response.handoff ?? [];
  const previousLedger = await readInterfaceLock(opts.outDir);
  const overlay = await applyOverlay(
    opts.outDir,
    handoffItems,
    previousLedger,
  );

  // Write the new ledger when non-empty (write-when-non-empty: a hand-off-free
  // / all-pending render writes no lockfile; readInterfaceLock treats absent as {}).
  // Also write when the previous ledger was non-empty and contracts became empty
  // (e.g., all entries cleared by drift) so stale on-disk data is overwritten.
  // readInterfaceLock treats both an absent file and an empty {} identically, so
  // writing {} is semantically equivalent to deleting the file — and avoids
  // needing an unlink call here.
  if (
    Object.keys(overlay.contracts).length > 0 ||
    Object.keys(previousLedger).length > 0
  ) {
    await writeInterfaceLock(opts.outDir, overlay.contracts);
  }

  // Decision 4 (ADR 054): non-fatal consistency check. Consumes applyOverlay's
  // enriched pending reasons + the in-memory previousLedger. Does NOT re-read
  // overlay files (the ADR explicitly rejected a redundant re-read; the reasons
  // already encode the necessary overlay-presence and stub-marker information).
  //
  // overlay-without-entry: a 'hash-drift' pending reason means the overlay was
  // present and stub-free (hash-drift is only reachable when overlayExists=true
  // and no stub marker fired — see applyOverlay's else-branch attribution). But
  // the stored/absent hash didn't match. This is the "copied bodies, lost ledger"
  // signature (the mro-incident footgun). Emit a warning naming the id and
  // pointing at the lockfile.
  // ADR 062 D4 (widen): the warning spans both trees — a body resolved from
  // spec/locked/ with no ledger entry produces 'hash-drift' and is correctly flagged.
  // OQ-F confirmation: the probe already attributes reason tree-agnostically, so
  // this widen is a no-op in code (the same branch fires for either tree).
  // The ledger is id-keyed and tree-agnostic (the surviving half of ADR 062 D4) and
  // now lives at spec/locked/interfaces.lock per ADR 066.
  //
  // entry-without-overlay (sub-case a): a 'no-overlay' pending reason for an id
  // that nonetheless has a prior lockfile entry — the overlay was deleted but the
  // ledger entry lingered. Emit a warning naming the dangling id.
  //
  // entry-without-overlay (sub-case b): a previousLedger key that is not present
  // in the current hand-off set at all — the hand-off was removed from the spec
  // but its lockfile entry lingered. Emit a warning naming the dangling id.
  //
  // 'stub-marker' reason is EXCLUDED from both — a legitimately-unimplemented
  // overlay does not "look implemented" and must not trigger the check.
  //
  // Decision 8 (ADR 062): emit a non-fatal warning when a hand-off's engine hint
  // is spec/locked/<rel> (locked: true declared) but the probe resolved the body
  // from spec/src/ (fallback) or it is missing. This is probe-vs-hint mismatch —
  // two different facts (hint reflects spec intent; probe reflects the filesystem).
  // The ledger is id-keyed and tree-agnostic; it lives at spec/locked/interfaces.lock
  // per ADR 066.
  const warnings: string[] = [];
  const handoffIdSet = new Set(handoffItems.map((h) => h.id));

  for (const p of overlay.pending) {
    if (p.reason === 'hash-drift') {
      warnings.push(
        `warning: hand-off '${p.item.id}' has a stub-free overlay but no matching ` +
        `entry in spec/locked/interfaces.lock — did you forget to copy the lockfile? ` +
        `Re-run the apply/record flow or copy the prior lock entry to resolve.`,
      );
    } else if (p.reason === 'no-overlay' && previousLedger[p.item.id] !== undefined) {
      warnings.push(
        `warning: hand-off '${p.item.id}' has a lockfile entry but no overlay file on disk ` +
        `(spec/locked/interfaces.lock may be stale — the overlay was deleted or moved).`,
      );
    }
  }

  // ADR 063 (amends ADR 062 D8): reconcile the overlay tree to the locked flag at render.
  // For each hand-off, if the body's physical tree disagrees with its spec-declared intent
  // (hintTree vs resolvedTree), core moves the body to the correct tree and reports it.
  // Both directions: lock (src→locked) and un-lock (locked→src). No git command (D2).
  // The move reports ride the existing warnings channel (D3 / OQ-5).
  const moveReports = await reconcileOverlayTree(opts.outDir, overlay.treeInfo);
  warnings.push(...moveReports);

  // Missing-body case (Contract #4 / ADR-063 M6): hintTree === 'locked' but resolvedTree
  // === null — nothing to move (body absent from both trees). Warn, reworded away from the
  // stale 'git mv' text (which would point at a non-existent file — nonsensical). The move
  // direction (resolvedTree === 'src') is now handled by reconcileOverlayTree above, not here.
  for (const item of handoffItems) {
    const info = overlay.treeInfo.get(item.id);
    if (info && info.hintTree === 'locked' && info.resolvedTree === null) {
      warnings.push(
        `warning: \`locked: true\` on hand-off \`${item.id}\` but its body exists in neither ` +
        `spec/src/ nor spec/locked/ — the overlay was never seeded or was deleted.`,
      );
    }
  }

  for (const key of Object.keys(previousLedger)) {
    if (!handoffIdSet.has(key)) {
      warnings.push(
        `warning: lockfile entry '${key}' has no corresponding hand-off in the current spec ` +
        `(spec/locked/interfaces.lock may have a dangling entry — was the hand-off removed?).`,
      );
    }
  }

  const environments = buildEnvironments(response.environments);
  const defaultEnvironment = response.default_environment;

  // Union newly-seeded once-ever paths into the prior tombstone (dedup via Set).
  const nextTombstone = [...new Set([...priorTombstone, ...seededOnceEverPaths])];

  const now = opts.now ? opts.now() : new Date();
  const inflightSlug = response.inflight_slug ?? null;
  const manifest = {
    schemaVersion: 1 as const,
    renderedAt: now.toISOString(),
    specPath: path.resolve(opts.specPath),
    files: trackedPaths,
    ...(nextTombstone.length > 0 ? { seededOnceEver: nextTombstone } : {}),
    ...(inflightSlug !== null
      ? {
          schema: {
            sqlserver: { inflightSlug },
          },
        }
      : {}),
    ...(environments ? { environments } : {}),
    ...(defaultEnvironment ? { defaultEnvironment } : {}),
  };
  await writeManifest(opts.outDir, manifest);

  return {
    ok: true,
    filesWritten: writtenPaths,
    filesRemoved: stalePaths,
    // Map enriched PendingHandoff[] back to bare HandoffItem[] so the CLI/plugin
    // surface (RenderHandoffOutcome.pending: HandoffItem[]) stays unchanged.
    handoff: { resolved: overlay.resolved, pending: overlay.pending.map((p) => p.item) },
    ...(warnings.length > 0 ? { warnings } : {}),
  };
}

async function readPriorMigrations(outDir: string): Promise<PriorMigrationFile[]> {
  // ADR 020 / ADR 066: cuts live under spec/locked/.../migrations/. The _inflight.sql
  // exclusion below is defensive — _inflight.sql should never appear under
  // spec/locked/.
  const dir = path.join(outDir, SPEC_MIGRATIONS_REL_DIR);
  let entries: string[];
  try {
    entries = await readdir(dir);
  } catch (err) {
    if (isNotFound(err)) return [];
    throw err;
  }
  const cuts = entries.filter(
    (name) => name.endsWith('.sql') && name !== INFLIGHT_FILENAME,
  );
  const out: PriorMigrationFile[] = [];
  for (const filename of cuts.sort()) {
    const contents = await readFile(path.join(dir, filename), 'utf8');
    out.push({ filename, contents });
  }
  return out;
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}

/**
 * Transform the engine-resolved environment list into the manifest's
 * keyed-by-name shape. Engine is the source of truth (ADR 010
 * follow-on): the `needs_sqlserver` boolean already accounts for
 * auto-port-binding + user-port-binding-override semantics.
 *
 * Returns `undefined` when the cloud response carries no
 * `environments` (older cloud builds, or specs with no
 * `environments:` block); the manifest then omits the block, and
 * tooling falls back to the `APP_PORT_BINDING` env-var path.
 */
function buildEnvironments(
  entries: EnvironmentManifestEntry[] | undefined,
): Record<string, EnvironmentManifest> | undefined {
  if (!entries || entries.length === 0) return undefined;
  const out: Record<string, EnvironmentManifest> = {};
  for (const entry of entries) {
    const env: EnvironmentManifest = {
      portBinding: entry.port_binding,
      data: entry.data,
      needsSqlserver: entry.needs_sqlserver,
    };
    if (entry.compute) {
      env.compute = entry.compute;
    }
    // ADR 024 — only record the appAdapters block when the cloud
    // actually populated it (older cloud builds may not). The apply
    // skill reads the field and falls back to `noop` when absent.
    if (entry.app_adapters?.auth?.id) {
      env.appAdapters = { auth: { id: entry.app_adapters.auth.id } };
    }
    out[entry.name] = env;
  }
  return out;
}

/**
 * Record that a hand-off has been resolved out-of-band — e.g. the apply
 * skill just had an agent fill in the overlay. Persists `hash` under
 * the interface lockfile (`spec/locked/interfaces.lock`) at `itemId` so the
 * next `render()` invocation's `applyOverlay()` step will copy the overlay
 * over `src/`. Creates the lockfile if it does not yet exist (create-if-absent
 * — Decision 3, ADR 054). No overlay-existence check: enforcement of the
 * overlay↔entry correspondence is the render-time consistency check's job.
 */
export async function recordHandoffResolution(
  outDir: string,
  itemId: string,
  hash: string,
): Promise<void> {
  const ledger = await readInterfaceLock(outDir);
  ledger[itemId] = hash;
  await writeInterfaceLock(outDir, ledger);
}
