export const LOCAL_DEV_URL = 'http://localhost:8100';

// deliberately NOT env-overridable (ADR D5) — this is only login's default
// for what gets written to the credentials file; login --cloud-url /
// $ARCHASCODE_DEV_CLOUD_URL already cover redirection.
export const HOSTED_CLOUD_URL = 'https://api.archascode.com';

export const COGNITO_REGION = 'us-east-1';

// Filled from `terraform output cognito_client_id` after first provision —
// see infra/README.md. Empty = not yet provisioned; login() fail-fasts.
export const COGNITO_CLIENT_ID = '5bll6vjhs6ivlqlik4kllt1i5j';

// Mirrors infra/cognito.tf: the pool declares no password_policy block, so
// Cognito's default policy applies. A public app client cannot query the
// policy at runtime (DescribeUserPool needs admin credentials), so it is
// baked here like COGNITO_CLIENT_ID — update alongside any policy change in
// the pool.
export const COGNITO_PASSWORD_REQUIREMENTS =
  'at least 8 characters, including an uppercase letter, a lowercase letter, a number, and a symbol';

export function cognitoClientId(env: NodeJS.ProcessEnv = process.env): string {
  return env.ARCHASCODE_COGNITO_CLIENT_ID ?? COGNITO_CLIENT_ID;
}

export function cognitoRegion(env: NodeJS.ProcessEnv = process.env): string {
  return env.ARCHASCODE_COGNITO_REGION ?? COGNITO_REGION;
}

export interface ResolveCloudUrlInput {
  /** flag / setting / tool arg — undefined when NOT supplied */
  explicit?: string;
  /** $ARCHASCODE_DEV_CLOUD_URL */
  env?: string;
  /** credentials-file cloudUrl */
  credentials?: string;
}

/**
 * The single presence rule for cloud-URL resolution tiers: a tier
 * participates iff its value is defined and non-empty after trimming.
 * Private helper of `resolveCloudUrl`.
 */
function isPresent(value: string | undefined): value is string {
  return value !== undefined && value.trim() !== '';
}

/**
 * Resolves the effective cloud URL by presence, not value: explicit > env
 * ($ARCHASCODE_DEV_CLOUD_URL) > credentials, each by presence (defined and
 * non-empty after trimming — an explicitly-passed empty string falls through
 * to the next tier). No value comparison is performed anywhere: an explicit
 * value byte-equal to LOCAL_DEV_URL still wins at the explicit tier
 * (Contract: ADR-071 #4). When all three tiers are absent, returns `null` —
 * no cloud URL is configured at any tier, for which "not logged in" is the
 * caller's account. Callers must not re-derive this fact from a downstream
 * network failure (ADR-071 Amendment A1).
 */
export function resolveCloudUrl(input: ResolveCloudUrlInput): string | null {
  if (isPresent(input.explicit)) {
    return input.explicit;
  }
  if (isPresent(input.env)) {
    return input.env;
  }
  if (isPresent(input.credentials)) {
    return input.credentials;
  }
  return null;
}

/**
 * True when `url`'s origin matches LOCAL_DEV_URL's origin (the localhost
 * dev default) — the single home of the D5 localhost-skip rule all three
 * frontends use to decide whether to attach an auth token. An unparseable
 * URL returns false rather than throwing; the real error surfaces later when
 * the caller actually tries to use the URL.
 */
export function isLocalDevOrigin(url: string): boolean {
  try {
    return new URL(url).origin === new URL(LOCAL_DEV_URL).origin;
  } catch {
    return false;
  }
}
