import { mkdir, readFile, writeFile } from 'node:fs/promises';
import * as path from 'node:path';

export const INTERFACES_LOCK_REL_PATH = path.join('spec', 'locked', 'interfaces.lock');

export async function readInterfaceLock(outDir: string): Promise<Record<string, string>> {
  const lockPath = path.join(outDir, INTERFACES_LOCK_REL_PATH);
  let raw: string;
  try {
    raw = await readFile(lockPath, 'utf8');
  } catch (err) {
    if (isNotFound(err)) return {};
    throw err;
  }
  return JSON.parse(raw) as Record<string, string>;
}

export async function writeInterfaceLock(
  outDir: string,
  map: Record<string, string>,
): Promise<void> {
  const lockPath = path.join(outDir, INTERFACES_LOCK_REL_PATH);
  await mkdir(path.dirname(lockPath), { recursive: true });
  await writeFile(lockPath, JSON.stringify(map, null, 2) + '\n', 'utf8');
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}
