// Shared set of all known stub markers — applyOverlay checks this set so the
// gate stays kind-agnostic (ADR 040's confirmed design). Any marker present in
// an overlay ⇒ pending; no `item.kind` branch needed.
//
// DELIBERATELY EXCLUDED: the jwt_bearer claims-mapper seed marker
// (`# archascode: seeded by jwt_bearer adapter renderer`, ADR 024 amended).
// A stub marker means "this overlay would crash/no-op if it ran — keep it
// pending." The claims-mapper seed is the opposite: runnable default-OIDC code.
// An un-customized jwt_bearer project must still get that seed promoted to src/
// and running, so its `auth_claims_mapper` hand-off resolves *with* its marker
// present. The seed marker is the apply skill's customize-or-not dispatch hint,
// NOT a promotion gate. Do not add it here.
export const STUB_MARKERS = [
  ENTITY_METHOD_STUB_MARKER,
  CUSTOM_PORT_ADAPTER_STUB_MARKER,
  CUSTOM_UC_WORKFLOW_STUB_MARKER,
  DOMAIN_SERVICE_BODY_STUB_MARKER,
  ENTITY_ADAPTER_STUB_MARKER,
] as const;
