import { access, mkdir, rm, writeFile } from 'node:fs/promises';
import * as path from 'node:path';

import type { RenderedFile } from 'archascode-protocol-ts';

export function assertSafeRelativePath(p: string): void {
  if (!p || p.trim() !== p) {
    throw new Error(`refusing empty/whitespace path: ${JSON.stringify(p)}`);
  }
  if (path.isAbsolute(p)) {
    throw new Error(`refusing absolute path from cloud: ${p}`);
  }
  const normalized = path.normalize(p);
  if (normalized.startsWith('..') || normalized.split(path.sep).includes('..')) {
    throw new Error(`refusing path traversal: ${p}`);
  }
}

export interface WriteFilesResult {
  /** Paths actually written this render — overwrite files plus first-time once/once-ever writes. */
  writtenPaths: string[];
  /** Once-policy paths that were skipped because the destination already exists. */
  skippedOncePaths: string[];
  /**
   * Once-ever paths that were written for the first time this render — i.e.
   * not tombstoned AND not already on disk. `render.ts` unions these into the
   * manifest's `seededOnceEver` tombstone. See ADR 055 amendment A2.
   */
  seededOnceEverPaths: string[];
}

export async function writeFiles(
  outDir: string,
  files: readonly RenderedFile[],
  tombstone: ReadonlySet<string> = new Set(),
): Promise<WriteFilesResult> {
  const written: string[] = [];
  const skipped: string[] = [];
  const seededOnceEver: string[] = [];
  for (const file of files) {
    assertSafeRelativePath(file.path);
    const dest = path.join(outDir, file.path);
    if (file.policy === 'once' && (await pathExists(dest))) {
      skipped.push(file.path);
      continue;
    }
    if (file.policy === 'once-ever' && (tombstone.has(file.path) || (await pathExists(dest)))) {
      // Skip: already tombstoned (delete sticks) or destination still exists on disk.
      continue;
    }
    await mkdir(path.dirname(dest), { recursive: true });
    await writeFile(dest, file.content, 'utf8');
    written.push(file.path);
    if (file.policy === 'once-ever') {
      seededOnceEver.push(file.path);
    }
  }
  return { writtenPaths: written, skippedOncePaths: skipped, seededOnceEverPaths: seededOnceEver };
}

async function pathExists(p: string): Promise<boolean> {
  try {
    await access(p);
    return true;
  } catch {
    return false;
  }
}

export async function deleteFiles(outDir: string, relPaths: readonly string[]): Promise<void> {
  for (const rel of relPaths) {
    if (!rel) continue;
    try {
      assertSafeRelativePath(rel);
    } catch {
      continue;
    }
    const dest = path.join(outDir, rel);
    await rm(dest, { force: true });
  }
}
