import type { RenderRequest, RenderResponse } from 'archascode-protocol-ts';

export type Fetcher = typeof fetch;

/**
 * Thrown when the cloud `/render` endpoint responds with a non-2xx status.
 * Carries the HTTP status so callers (frontends) can special-case 401s with
 * a "run `archascode login`" hint (ADR 071).
 */
export class CloudRequestError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = 'CloudRequestError';
  }
}

export async function postRender(
  cloudUrl: string,
  req: RenderRequest,
  fetcher: Fetcher = fetch,
  authToken?: string,
): Promise<RenderResponse> {
  const url = new URL('/render', cloudUrl);
  const res = await fetcher(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(authToken ? { authorization: `Bearer ${authToken}` } : {}),
    },
    body: JSON.stringify(req),
  });
  if (!res.ok) {
    const detail = await safeReadText(res);
    throw new CloudRequestError(
      `cloud /render returned ${res.status} ${res.statusText}${detail ? `: ${detail}` : ''}`,
      res.status,
    );
  }
  return (await res.json()) as RenderResponse;
}

async function safeReadText(res: Response): Promise<string> {
  try {
    return await res.text();
  } catch {
    return '';
  }
}
