import { chmod, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import * as os from 'node:os';
import * as path from 'node:path';

import type { Fetcher } from './client';
import {
  cognitoClientId,
  cognitoRegion,
  COGNITO_PASSWORD_REQUIREMENTS,
  HOSTED_CLOUD_URL,
} from './config';

/** Cached Cognito session for a logged-in user (ADR 071). */
export interface Credentials {
  username: string;
  refreshToken: string;
  accessToken: string;
  /** ISO timestamp. */
  accessTokenExpiresAt: string;
  clientId: string;
  region: string;
  cloudUrl: string;
}

/**
 * Resolves the credentials cache file path: `$ARCHASCODE_CREDENTIALS_PATH`
 * when set (a hermeticity seam for process-level consumers — ADR-071 D5),
 * else `~/.archascode/credentials.json`.
 */
export function defaultCredentialsPath(): string {
  const override = process.env.ARCHASCODE_CREDENTIALS_PATH;
  if (override) {
    return override;
  }
  return path.join(os.homedir(), '.archascode', 'credentials.json');
}

// A credentials file is written with owner-only read/write — it holds a
// live refresh token.
const CREDENTIALS_FILE_MODE = 0o600;

/**
 * Unsigned JSON POST to Cognito's public-client IDP endpoint. No AWS SDK,
 * no SigV4 — InitiateAuth/RespondToAuthChallenge on a public app client are
 * unauthenticated JSON RPCs (ADR-071 Rationale: a `@aws-sdk/*` dependency in
 * packages/core would be pulled into every consumer just to format three
 * JSON bodies).
 */
async function cognitoRequest(
  region: string,
  target: 'InitiateAuth' | 'RespondToAuthChallenge',
  body: unknown,
  fetcher: Fetcher,
): Promise<{ ok: boolean; status: number; json: () => Promise<unknown> }> {
  const res = await fetcher(`https://cognito-idp.${region}.amazonaws.com/`, {
    method: 'POST',
    headers: {
      'content-type': 'application/x-amz-json-1.1',
      'x-amz-target': `AWSCognitoIdentityProviderService.${target}`,
    },
    body: JSON.stringify(body),
  });
  return res;
}

/**
 * Best-effort extraction of a Cognito error body (`{__type, message}` under
 * amz-json-1.1) from a non-2xx response, tolerating a non-JSON body.
 */
async function cognitoErrorDetail(res: {
  status: number;
  json: () => Promise<unknown>;
}): Promise<{ type: string; message: string }> {
  try {
    const body = (await res.json()) as { __type?: string; message?: string };
    return {
      type: body.__type ?? '',
      message: body.message ?? body.__type ?? `HTTP ${res.status}`,
    };
  } catch {
    return { type: '', message: `HTTP ${res.status}` };
  }
}

async function writeCredentials(
  credentialsPath: string,
  creds: Credentials,
): Promise<void> {
  await mkdir(path.dirname(credentialsPath), { recursive: true });
  await writeFile(credentialsPath, JSON.stringify(creds, null, 2) + '\n', {
    mode: CREDENTIALS_FILE_MODE,
  });
  // writeFile's `mode` only applies when the file is created; if it already
  // existed (e.g. a refresh rewrite) the prior mode carries over, so
  // re-apply explicitly.
  await chmod(credentialsPath, CREDENTIALS_FILE_MODE);
}

export interface LoginOptions {
  username: string;
  password: string;
  /** Default HOSTED_CLOUD_URL — what gets RECORDED in the credentials file (ADR-071 D5). */
  cloudUrl?: string;
  /** Default `cognitoClientId()`. */
  clientId?: string;
  /** Default `cognitoRegion()`. */
  region?: string;
  /** Default `defaultCredentialsPath()`. */
  credentialsPath?: string;
  fetcher?: Fetcher;
  now?: () => Date;
  /** NEW_PASSWORD_REQUIRED hatch — invite-only means this is every new user's first login. */
  promptNewPassword?: () => Promise<string>;
}

/**
 * `USER_PASSWORD_AUTH` login against the Cognito public app client,
 * completing the `NEW_PASSWORD_REQUIRED` challenge inline when Cognito
 * demands it (ADR-071 Contract #3). Writes the credentials file on success
 * and returns what was written.
 */
export async function login(opts: LoginOptions): Promise<Credentials> {
  const fetcher = opts.fetcher ?? fetch;
  const now = opts.now ?? (() => new Date());
  const region = opts.region ?? cognitoRegion();
  const clientId = opts.clientId ?? cognitoClientId();
  const credentialsPath = opts.credentialsPath ?? defaultCredentialsPath();
  const cloudUrl = opts.cloudUrl ?? HOSTED_CLOUD_URL;

  if (!clientId) {
    throw new Error(
      'archascode cloud auth is not yet provisioned: ARCHASCODE_COGNITO_CLIENT_ID is unset ' +
        'and no client id has been baked in — see infra/README.md',
    );
  }

  const initRes = await cognitoRequest(
    region,
    'InitiateAuth',
    {
      AuthFlow: 'USER_PASSWORD_AUTH',
      ClientId: clientId,
      AuthParameters: { USERNAME: opts.username, PASSWORD: opts.password },
    },
    fetcher,
  );
  if (!initRes.ok) {
    const err = await cognitoErrorDetail(initRes);
    throw new Error(`Cognito login failed: ${err.message}`);
  }
  const initJson = (await initRes.json()) as {
    ChallengeName?: string;
    Session?: string;
    AuthenticationResult?: {
      AccessToken: string;
      RefreshToken?: string;
      ExpiresIn: number;
    };
  };

  let authResult = initJson.AuthenticationResult;

  if (initJson.ChallengeName === 'NEW_PASSWORD_REQUIRED') {
    if (!opts.promptNewPassword) {
      throw new Error(
        'Cognito requires a new password on first login (NEW_PASSWORD_REQUIRED) but no ' +
          'promptNewPassword callback was provided',
      );
    }
    const newPassword = await opts.promptNewPassword();
    const challengeRes = await cognitoRequest(
      region,
      'RespondToAuthChallenge',
      {
        ChallengeName: 'NEW_PASSWORD_REQUIRED',
        ClientId: clientId,
        Session: initJson.Session,
        ChallengeResponses: {
          USERNAME: opts.username,
          NEW_PASSWORD: newPassword,
        },
      },
      fetcher,
    );
    if (!challengeRes.ok) {
      const err = await cognitoErrorDetail(challengeRes);
      if (err.type === 'InvalidPasswordException') {
        throw new Error(
          `Cognito rejected the new password: ${err.message} ` +
            `(passwords must be ${COGNITO_PASSWORD_REQUIREMENTS})`,
        );
      }
      throw new Error(`Cognito new-password challenge failed: ${err.message}`);
    }
    const challengeJson = (await challengeRes.json()) as {
      AuthenticationResult?: {
        AccessToken: string;
        RefreshToken?: string;
        ExpiresIn: number;
      };
    };
    authResult = challengeJson.AuthenticationResult;
  }

  if (!authResult) {
    // Both calls returned 2xx yet no result — e.g. an unsupported challenge
    // type (MFA) this flow doesn't handle.
    throw new Error(
      initJson.ChallengeName && initJson.ChallengeName !== 'NEW_PASSWORD_REQUIRED'
        ? `Cognito returned an unsupported challenge: ${initJson.ChallengeName}`
        : 'Cognito login did not return an AuthenticationResult',
    );
  }

  const accessTokenExpiresAt = new Date(
    now().getTime() + authResult.ExpiresIn * 1000,
  ).toISOString();

  const creds: Credentials = {
    username: opts.username,
    refreshToken: authResult.RefreshToken ?? '',
    accessToken: authResult.AccessToken,
    accessTokenExpiresAt,
    clientId,
    region,
    cloudUrl,
  };

  await writeCredentials(credentialsPath, creds);
  return creds;
}

export interface GetAuthTokenOptions {
  credentialsPath?: string;
  fetcher?: Fetcher;
  now?: () => Date;
}

// Refresh a cached access token this far ahead of its recorded expiry, to
// absorb clock skew and in-flight request latency (ADR-071 Fork F13).
const EXPIRY_SKEW_MS = 60_000;

/**
 * Returns a valid access token, refreshing via `REFRESH_TOKEN_AUTH` when the
 * cached one is missing or within `EXPIRY_SKEW_MS` of expiring. Never
 * throws: an absent/unreadable/unparsable credentials file, or any refresh
 * failure (non-2xx response, thrown fetch), returns `null` — the caller
 * proceeds unauthenticated and any resulting 401 carries a "run
 * `archascode login`" hint (ADR-071 D5).
 */
export async function getAuthToken(
  opts: GetAuthTokenOptions = {},
): Promise<string | null> {
  const credentialsPath = opts.credentialsPath ?? defaultCredentialsPath();
  const fetcher = opts.fetcher ?? fetch;
  const now = opts.now ?? (() => new Date());

  const creds = await readCredentials(credentialsPath);
  if (!creds) {
    return null;
  }

  const expiresAt = Date.parse(creds.accessTokenExpiresAt);
  if (!Number.isNaN(expiresAt) && expiresAt - now().getTime() > EXPIRY_SKEW_MS) {
    return creds.accessToken;
  }

  try {
    const res = await cognitoRequest(
      creds.region,
      'InitiateAuth',
      {
        AuthFlow: 'REFRESH_TOKEN_AUTH',
        ClientId: creds.clientId,
        AuthParameters: { REFRESH_TOKEN: creds.refreshToken },
      },
      fetcher,
    );
    if (!res.ok) {
      return null;
    }
    const json = (await res.json()) as {
      AuthenticationResult?: {
        AccessToken: string;
        RefreshToken?: string;
        ExpiresIn: number;
      };
    };
    const authResult = json.AuthenticationResult;
    if (!authResult) {
      return null;
    }
    const accessTokenExpiresAt = new Date(
      now().getTime() + authResult.ExpiresIn * 1000,
    ).toISOString();
    const refreshed: Credentials = {
      ...creds,
      accessToken: authResult.AccessToken,
      // Cognito's refresh response typically omits RefreshToken; keep the
      // existing one when so.
      refreshToken: authResult.RefreshToken ?? creds.refreshToken,
      accessTokenExpiresAt,
    };
    await writeCredentials(credentialsPath, refreshed);
    return refreshed.accessToken;
  } catch {
    return null;
  }
}

/**
 * Reads the credentials file without refreshing — the frontends' URL
 * resolution tier needs `cloudUrl` without a Cognito round-trip. Returns
 * `null` when the file is absent, unreadable, or unparsable.
 */
export async function readCredentials(
  credentialsPath?: string,
): Promise<Credentials | null> {
  const resolvedPath = credentialsPath ?? defaultCredentialsPath();
  try {
    const raw = await readFile(resolvedPath, 'utf8');
    return JSON.parse(raw) as Credentials;
  } catch {
    return null;
  }
}

/**
 * Deletes the credentials file. Returns `true` iff it existed. File
 * deletion lives in core (not the CLI) so the path-resolution logic has one
 * home (ADR-071 Fork F6).
 */
export async function logout(credentialsPath?: string): Promise<boolean> {
  const resolvedPath = credentialsPath ?? defaultCredentialsPath();
  try {
    await rm(resolvedPath);
    return true;
  } catch {
    return false;
  }
}
