import { spawn } from 'node:child_process';
import { readFile, readdir } from 'node:fs/promises';
import * as path from 'node:path';

import { hasMeaningfulContent, readManifest } from 'archascode-core';

export const INFLIGHT_REL_PATH = path.join(
  'src',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
  '_inflight.sql',
);
export const SPEC_MIGRATIONS_REL_DIR = path.join(
  'spec',
  'locked',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
);

/**
 * Cut filename shape: `<14-digit-timestamp>_<slug>.sql`. `_inflight.sql`
 * doesn't live in spec/locked/ but we still skip it defensively.
 */
export const CUT_FILENAME_RE = /^\d{14}_[a-z0-9_]+\.sql$/;

export interface DeployInputs {
  outDir: string;
  envName: string;
  baselineExisting: boolean;
  mode: 'plan' | 'apply';
  planOut?: string;
  upTo?: string;
}

export interface DeployIO {
  /** stderr sink. Defaults to writing process.stderr. */
  stderr: (text: string) => void;
  /** Invoked once preconditions pass. Returns the subprocess exit code. */
  invokeMigrate: (input: InvokeMigrateInput) => Promise<number>;
  /** Reads the manifest from outDir. Defaults to `archascode-core.readManifest`. */
  readManifest?: typeof readManifest;
}

export interface InvokeMigrateInput {
  outDir: string;
  envName: string;
  baselineExisting: boolean;
  mode: 'plan' | 'apply';
  planOut?: string;
  upTo?: string;
}

/**
 * Implements `aac deploy --env <name>`.
 *
 * Preconditions, in order:
 *   1. --env value must resolve to an environment in the rendered
 *      manifest (else exit 2).
 *   2. `_inflight.sql` must be empty (else exit 1).
 *   3. Every committable cut file under spec/locked/.../migrations/ must
 *      be tracked-and-clean in git (else exit 1).
 *
 * If the env's data axis is `ephemeral`, prints a one-line nudge to
 * stderr and proceeds.
 *
 * Once preconditions pass, delegates to the injected `invokeMigrate`
 * (the production entry uses `uv run python aac.py --env <name> migrate`).
 */
export async function runDeploy(
  input: DeployInputs,
  io: DeployIO,
): Promise<number> {
  const { outDir, envName, baselineExisting, mode, planOut, upTo } = input;
  const readManifestFn = io.readManifest ?? readManifest;

  const manifest = await readManifestFn(outDir);
  const env = manifest?.environments?.[envName] ?? null;
  if (env === null) {
    io.stderr(`deploy: env ${envName} not found in manifest\n`);
    return 2;
  }

  if (env.data === 'ephemeral') {
    io.stderr(
      `archascode: env ${envName} is data: ephemeral — for quicker dev iteration, use 'aac up'\n`,
    );
  }

  const inflightPath = path.join(outDir, INFLIGHT_REL_PATH);
  if (await inflightHasDelta(inflightPath)) {
    io.stderr(
      "archascode: uncommitted schema changes in _inflight.sql. " +
        "Run 'aac cut-schema-migration' first.\n",
    );
    return 1;
  }

  const uncommitted = await uncommittedCuts(outDir);
  if (uncommitted.length > 0) {
    io.stderr(
      `archascode: the following cut files are not committed to git:\n`,
    );
    for (const f of uncommitted) io.stderr(`  ${f}\n`);
    io.stderr('Commit them before deploying.\n');
    return 1;
  }

  return await io.invokeMigrate({ outDir, envName, baselineExisting, mode, planOut, upTo });
}

async function inflightHasDelta(inflightPath: string): Promise<boolean> {
  let body: string;
  try {
    body = await readFile(inflightPath, 'utf8');
  } catch (err) {
    if (isNotFound(err)) return false;
    throw err;
  }
  return hasMeaningfulContent(body);
}

async function uncommittedCuts(outDir: string): Promise<string[]> {
  const cutsDir = path.join(outDir, SPEC_MIGRATIONS_REL_DIR);
  let entries: string[];
  try {
    entries = await readdir(cutsDir);
  } catch (err) {
    if (isNotFound(err)) return [];
    throw err;
  }
  const cutFiles = entries
    .filter((name) => CUT_FILENAME_RE.test(name))
    .sort();
  const offending: string[] = [];
  for (const name of cutFiles) {
    const rel = path.join(SPEC_MIGRATIONS_REL_DIR, name);
    if (!(await isPathClean(outDir, rel))) {
      offending.push(rel);
    }
  }
  return offending;
}

async function isPathClean(outDir: string, relPath: string): Promise<boolean> {
  // `git status --porcelain -- <path>` prints one line per dirty entry
  // and nothing if the path is tracked-and-clean. We don't care which
  // flavour of dirt (untracked / modified / staged) — any of them
  // means "not committed".
  const result = await runCommand(
    'git',
    ['status', '--porcelain', '--', relPath],
    outDir,
  );
  if (result.code !== 0) {
    // Not a git repo, or some other git failure — treat as uncommitted
    // so the user is forced to address it explicitly rather than the
    // verb silently waving through.
    return false;
  }
  return result.stdout.trim().length === 0;
}

/**
 * Build the argv for the migrate spawn: `uv run python aac.py --env
 * NAME migrate`.
 *
 * `uv run` (not bare `python`) is the load-bearing choice. Per ADR 050
 * the rendered project relies on a real editable install — `adapter`,
 * `api`, etc. are top-level packages registered by `uv sync` into the
 * project's `.venv`, and `aac.py`'s schema import (`from adapter.persistence
 * .sqlserver.apply_schema import ...`) resolves *only* through that install.
 * A bare `python aac.py` spawn runs under whatever interpreter is on PATH
 * (a pyenv shim, system python) which has no editable install of the
 * project, so the import fails with `ModuleNotFoundError: No module named
 * 'adapter'`. `uv run` from the project dir selects the `.venv` where the
 * install lives, matching the launcher contract the plugin's `aac up` path
 * already uses (`aacUpCommand.ts`). Exported for unit assertion on the
 * exact command line (the spawn itself isn't exercised in tests).
 */
export function buildMigrateCommand(envName: string): {
  cmd: string;
  args: string[];
} {
  return {
    cmd: 'uv',
    args: ['run', 'python', 'aac.py', '--env', envName, 'migrate'],
  };
}

/**
 * Builds the env-var delta `defaultInvokeMigrate` layers onto
 * `process.env` for the migrate spawn — a pure assembler with no combo
 * guard (ADR 069, Fork F7: Contract #3's two layers are the CLI handlers
 * and the rendered module; a guard here would be an undeclared third).
 * Extracted from `defaultInvokeMigrate` so the "env var actually set"
 * behavior is directly assertable — the spawn itself stays deliberately
 * untested.
 */
export function buildMigrateEnv(
  input: InvokeMigrateInput,
): Record<string, string> {
  const env: Record<string, string> = {};
  if (input.baselineExisting) {
    env.ARCHASCODE_BASELINE_EXISTING = '1';
  }
  if (input.mode === 'plan') {
    env.ARCHASCODE_DRY_RUN = '1';
  }
  if (input.planOut) {
    env.ARCHASCODE_PLAN_OUT = input.planOut;
  }
  if (input.upTo) {
    env.ARCHASCODE_UP_TO = input.upTo;
  }
  return env;
}

/**
 * Default `invokeMigrate` implementation: spawn `uv run python aac.py
 * --env NAME migrate` in outDir with `ARCHASCODE_BASELINE_EXISTING=1` set
 * when baseline-existing mode is requested. The CLI's job ends at
 * preconditions; everything downstream is the lifecycle script's job.
 */
export const defaultInvokeMigrate = async (
  input: InvokeMigrateInput,
): Promise<number> => {
  const env: NodeJS.ProcessEnv = { ...process.env, ...buildMigrateEnv(input) };
  const { cmd, args } = buildMigrateCommand(input.envName);
  return new Promise<number>((resolve, reject) => {
    const child = spawn(cmd, args, {
      cwd: input.outDir,
      stdio: 'inherit',
      env,
    });
    child.on('error', reject);
    child.on('exit', (code, signal) => {
      if (signal !== null) {
        resolve(128);
        return;
      }
      resolve(code ?? 0);
    });
  });
};

interface CommandResult {
  code: number;
  stdout: string;
  stderr: string;
}

async function runCommand(
  cmd: string,
  args: string[],
  cwd: string,
): Promise<CommandResult> {
  return new Promise<CommandResult>((resolve, reject) => {
    const child = spawn(cmd, args, { cwd });
    let stdout = '';
    let stderr = '';
    child.stdout?.on('data', (chunk) => (stdout += chunk.toString()));
    child.stderr?.on('data', (chunk) => (stderr += chunk.toString()));
    child.on('error', reject);
    child.on('exit', (code) => resolve({ code: code ?? 0, stdout, stderr }));
  });
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}
