import { mkdir, readFile, writeFile } from 'node:fs/promises';
import * as path from 'node:path';

import { readManifest } from './manifest';

export interface CutSchemaMigrationOptions {
  /** Output directory of the rendered project (same `outDir` as `render`). */
  outDir: string;
  /**
   * Optional slug override. Normalized to ``lowercase_snake_case``. When
   * absent, falls back to the manifest's cached `inflightSlug`, then to
   * the generic `update_schema`.
   */
  name?: string;
  /** Override the wall clock (for tests). */
  now?: () => Date;
}

export type CutSchemaMigrationOutcome =
  | { ok: true; producedFilename: string }
  | { ok: false; reason: 'no-inflight' | 'missing-inflight-file'; message: string };

const MIGRATIONS_REL_DIR = path.join(
  'src',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
);
const SPEC_MIGRATIONS_REL_DIR = path.join(
  'spec',
  'locked',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
);
const INFLIGHT_FILENAME = '_inflight.sql';
const FALLBACK_SLUG = 'update_schema';
const EMPTY_INFLIGHT_BODY =
  '-- Generated by archascode — no pending schema changes\n';

export async function cutSchemaMigration(
  opts: CutSchemaMigrationOptions,
): Promise<CutSchemaMigrationOutcome> {
  const migrationsDir = path.join(opts.outDir, MIGRATIONS_REL_DIR);
  const inflightPath = path.join(migrationsDir, INFLIGHT_FILENAME);

  let inflightBody: string;
  try {
    inflightBody = await readFile(inflightPath, 'utf8');
  } catch (err) {
    if (isNotFound(err)) {
      return {
        ok: false,
        reason: 'missing-inflight-file',
        message: `no _inflight.sql at ${inflightPath}; run \`archascode render\` first`,
      };
    }
    throw err;
  }

  if (!hasMeaningfulContent(inflightBody)) {
    return {
      ok: false,
      reason: 'no-inflight',
      message:
        'no in-flight changes; nothing to cut. Run `archascode render` after editing the spec to populate.',
    };
  }

  const slug = resolveSlug(opts.name, await readCachedSlug(opts.outDir));
  const timestamp = formatTimestamp(opts.now ? opts.now() : new Date());
  const finalFilename = `${timestamp}_${slug}.sql`;
  const specMigrationsDir = path.join(opts.outDir, SPEC_MIGRATIONS_REL_DIR);
  const specCutPath = path.join(specMigrationsDir, finalFilename);
  const projectedCutPath = path.join(migrationsDir, finalFilename);

  // ADR 020 (per ADR-066): cuts live under spec/locked/ (canonical). ADR 021's apply
  // module reads from src/.../migrations/ (the projection that render
  // maintains). Without writing both at cut time, the projected
  // directory lags spec/locked/ between `cut` and the next `render` —
  // which is enough lag for `archascode deploy` to miss the new cut
  // entirely and report "schema_version is current" against the stale
  // projection. Cut both files here so deploy works without a
  // re-render in between.
  await mkdir(specMigrationsDir, { recursive: true });

  // Write the new cut to both trees, then truncate _inflight.sql.
  // Order matters for recovery: if anything fails before the truncate,
  // a re-run of `cut-schema-migration` re-reads the same inflight bytes
  // and produces the same content (idempotent up to timestamp). The
  // truncate is last so a mid-cut crash leaves the inflight content
  // recoverable.
  await writeFile(specCutPath, inflightBody, 'utf8');
  await writeFile(projectedCutPath, inflightBody, 'utf8');
  await writeFile(inflightPath, EMPTY_INFLIGHT_BODY, 'utf8');

  return { ok: true, producedFilename: finalFilename };
}

export function hasMeaningfulContent(sql: string): boolean {
  for (const rawLine of sql.split('\n')) {
    const line = rawLine.trim();
    if (!line) continue;
    if (line.startsWith('--')) continue;
    return true;
  }
  return false;
}

async function readCachedSlug(outDir: string): Promise<string | null> {
  const manifest = await readManifest(outDir);
  return manifest?.schema?.sqlserver?.inflightSlug ?? null;
}

function resolveSlug(
  override: string | undefined,
  cached: string | null,
): string {
  if (override !== undefined && override.length > 0) {
    return normalizeSlug(override);
  }
  if (cached !== null && cached.length > 0) {
    return normalizeSlug(cached);
  }
  return FALLBACK_SLUG;
}

function normalizeSlug(raw: string): string {
  const lowered = raw.trim().toLowerCase();
  const collapsed = lowered.replace(/[^a-z0-9_]+/g, '_').replace(/_+/g, '_');
  const trimmed = collapsed.replace(/^_+|_+$/g, '');
  return trimmed.length > 0 ? trimmed : FALLBACK_SLUG;
}

function formatTimestamp(now: Date): string {
  const y = now.getUTCFullYear().toString().padStart(4, '0');
  const mo = (now.getUTCMonth() + 1).toString().padStart(2, '0');
  const d = now.getUTCDate().toString().padStart(2, '0');
  const h = now.getUTCHours().toString().padStart(2, '0');
  const mi = now.getUTCMinutes().toString().padStart(2, '0');
  const s = now.getUTCSeconds().toString().padStart(2, '0');
  return `${y}${mo}${d}${h}${mi}${s}`;
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}

