import { readdir, rm, stat } from 'node:fs/promises';
import * as path from 'node:path';

import { readManifest } from './manifest';

/**
 * Debug-grade teardown verb: delete the whole render output surface and
 * leave "nothing but architecture.yml". The inverse of `render`.
 *
 * This is intentionally NOT a flag on `render`/`aac-apply` (the verb you
 * run reflexively — destructive proximity is a footgun) nor on `init`
 * (additive/idempotent, owns a different layer). It's a separate verb so
 * the destructiveness is legible at the call site. It is also deliberately
 * lightweight and un-ADR'd: it exists for debugging ("start from scratch")
 * and may be removed or solidified later — solidifying is ADR time.
 *
 * What it deletes (the full render surface — see engine layout/standard.py):
 *   - `src/`                      — engine output, always-overwrite
 *   - `spec/src/`                 — the regenerable agent overlay (body seeds,
 *                                   __init__.py markers). Purely regenerable:
 *                                   everything in it comes back on the next
 *                                   render. Deleted wholesale by default clean
 *                                   (no carve-out needed — ADR 066).
 *   - `.archascode/manifest.json` — render bookkeeping
 *   - `aac.py`                    — root overwrite file
 *   - `docker-compose.yml`        — root once-seed (user-owned after first
 *                                   render); warned about.
 *
 * What it preserves (NOT render output):
 *   - `spec/architecture.yml`            — the source of truth (the point)
 *   - `spec/.archascode/positions.json`  — plugin editor state, a *different*
 *                                          `.archascode` dir from the manifest
 *   - `spec/locked/`                     — the non-regenerable overlay tree:
 *                                          hand-authored bodies, sealed schema
 *                                          cuts, and the interface-resolution
 *                                          ledger. Preserved by tree membership
 *                                          (never a default clean target).
 *   - `pyproject.toml`, `.venv/`         — owned by /aac-init
 *   - `.env.<env>.example`               — per-environment example templates
 *                                          (the emit-once-ever tombstone lives
 *                                          in the manifest, which `clean` DOES
 *                                          delete; so `clean` resets the
 *                                          tombstone — by design. A fresh
 *                                          render will re-seed examples if
 *                                          they are absent, and skip them if
 *                                          still on disk. Do NOT "fix" clean
 *                                          to preserve the tombstone — that
 *                                          would defeat clean's reset
 *                                          semantics. See ADR 055 amendment
 *                                          A6 for the rationale.)
 *
 * Deletion is driven by directory layout, not the manifest: the manifest
 * deliberately does not track `spec/src/` once-seeds, so it cannot find
 * them. The manifest is read only to surface warnings (deployed envs).
 */

/** Relative paths (from `outDir`) that `clean` removes. */
export const CLEAN_TARGETS = [
  'src',
  path.join('spec', 'src'),
  path.join('.archascode', 'manifest.json'),
  'aac.py',
  'docker-compose.yml',
] as const;

const SPEC_MIGRATIONS_REL_DIR = path.join(
  'spec',
  'locked',
  'adapter',
  'persistence',
  'sqlserver',
  'schema',
  'migrations',
);
const INFLIGHT_FILENAME = '_inflight.sql';
const CUT_FILENAME_RX = /^\d{14}_[a-z0-9_]+\.sql$/;

export interface CleanProjectOptions {
  /** Output directory of the rendered project (same `outDir` as `render`). */
  outDir: string;
  /**
   * When true, performs a total reset: deletes spec/src/ and spec/locked/
   * wholesale (including the interface-resolution ledger and sealed migrations
   * in spec/locked/). Use only to rebuild from zero.
   *
   * When false (default), deletes the regenerable surface wholesale: src/,
   * aac.py, docker-compose.yml, manifest, and spec/src/ (entirely — no
   * carve-outs). Preserves spec/locked/ entirely by tree membership (it
   * holds the hand-authored bodies, sealed cuts, and the ledger).
   * ADR 062 D2 / ADR 066 D3.
   */
  hard?: boolean;
}

export interface CleanPlan {
  /** Targets that exist on disk and will be removed (relative paths). */
  targets: string[];
  /**
   * Non-blocking warnings the caller should surface before confirming.
   * `clean` never refuses — git is the safety net — but a sealed migration
   * or deployed environment is worth a heads-up.
   */
  warnings: string[];
}

export interface CleanResult {
  /** Targets actually removed (relative paths that existed). */
  removed: string[];
}

/**
 * Probe the project and return what `clean` would delete plus any warnings,
 * WITHOUT touching the filesystem. The caller (CLI) shows this, prompts for
 * confirmation, then calls `cleanProject`.
 *
 * ADR 062 D2 / ADR 066 D3: default (`hard: false`) deletes the regenerable
 * surface wholesale — spec/src/ is a plain target (no carve-outs); spec/locked/
 * is never touched (preserved by tree membership). `hard: true` is the total
 * reset: the default targets plus spec/locked/.
 */
export async function planClean(opts: CleanProjectOptions): Promise<CleanPlan> {
  const hard = opts.hard ?? false;
  const targets: string[] = [];
  const warnings: string[] = [];

  if (hard) {
    // --hard: wholesale delete of all CLEAN_TARGETS + spec/locked/
    const hardTargets = [
      ...CLEAN_TARGETS,
      path.join('spec', 'locked'),
    ] as readonly string[];
    for (const rel of hardTargets) {
      if (await pathExists(path.join(opts.outDir, rel))) {
        targets.push(rel);
      }
    }

    // Sealed-cut and deployed-env warnings only on --hard (default no longer
    // threatens these artifacts — they live in spec/locked/, preserved by
    // tree membership on the default path).
    const sealedCuts = await listSealedCuts(opts.outDir);
    if (sealedCuts.length > 0) {
      warnings.push(
        `${sealedCuts.length} sealed schema migration(s) under ${SPEC_MIGRATIONS_REL_DIR} ` +
          `will be deleted (${sealedCuts.join(', ')}). The next render re-derives ` +
          `schema from zero.`,
      );
    }

    const deployedEnvs = await listDeployedEnvironments(opts.outDir);
    if (deployedEnvs.length > 0) {
      warnings.push(
        `the manifest records environment(s) ${deployedEnvs.join(', ')}; ` +
          `deleting the migration chain may desync a deployed target.`,
      );
    }
  } else {
    // Default: delete src/, manifest, aac.py, docker-compose.yml, and
    // spec/src/ wholesale (purely regenerable — no carve-outs needed, ADR 066).
    // spec/locked/ is never listed as a target (preserved by tree membership).
    const defaultTopTargets = [
      'src',
      path.join('.archascode', 'manifest.json'),
      'aac.py',
      'docker-compose.yml',
    ] as const;
    for (const rel of defaultTopTargets) {
      if (await pathExists(path.join(opts.outDir, rel))) {
        targets.push(rel);
      }
    }
    // spec/src/ is a plain wholesale-delete target (no carve-out survivors).
    if (await pathExists(path.join(opts.outDir, 'spec', 'src'))) {
      targets.push(path.join('spec', 'src'));
    }
    // No warnings on default path — cuts and locked bodies are preserved in
    // spec/locked/ by tree membership.
  }

  return { targets, warnings };
}

/**
 * Delete the render output surface. Idempotent: missing targets are no-ops.
 * Returns the relative paths that actually existed and were removed.
 *
 * ADR 062 D2 / ADR 066 D3:
 * - Default (`hard: false`): wholesale delete of all regenerable targets
 *   (spec/src/ deleted entirely — no carve-outs; spec/locked/ is never touched,
 *   preserved by tree membership).
 * - `hard: true`: total reset — wholesale delete including spec/locked/.
 */
export async function cleanProject(
  opts: CleanProjectOptions,
): Promise<CleanResult> {
  const hard = opts.hard ?? false;
  const removed: string[] = [];

  if (hard) {
    // Total reset: delete all CLEAN_TARGETS wholesale + spec/locked/.
    const hardTargets = [
      ...CLEAN_TARGETS,
      path.join('spec', 'locked'),
    ] as readonly string[];
    for (const rel of hardTargets) {
      const dest = path.join(opts.outDir, rel);
      if (!(await pathExists(dest))) continue;
      await rm(dest, { recursive: true, force: true });
      removed.push(rel);
    }
  } else {
    // Default: wholesale delete of all regenerable CLEAN_TARGETS.
    // spec/src/ is deleted entirely (no carve-outs — it is purely regenerable,
    // ADR 066). spec/locked/ is never touched (preserved by tree membership).
    for (const rel of CLEAN_TARGETS) {
      const dest = path.join(opts.outDir, rel);
      if (!(await pathExists(dest))) continue;
      await rm(dest, { recursive: true, force: true });
      removed.push(rel);
    }
  }

  return { removed };
}

// pruneEmptyDirs remains exported in overlayMove.ts (used by reconcileOverlayTree,
// ADR 063). The import from overlayMove is NOT needed here after removing the
// spec/src/ partition walk (ADR 066 D3).

async function listSealedCuts(outDir: string): Promise<string[]> {
  const dir = path.join(outDir, SPEC_MIGRATIONS_REL_DIR);
  let entries: string[];
  try {
    entries = await readdir(dir);
  } catch (err) {
    if (isNotFound(err)) return [];
    throw err;
  }
  return entries
    .filter((name) => name !== INFLIGHT_FILENAME && CUT_FILENAME_RX.test(name))
    .sort();
}

async function listDeployedEnvironments(outDir: string): Promise<string[]> {
  const manifest = await readManifest(outDir);
  if (!manifest?.environments) return [];
  // Any environment whose port binding routes to sqlserver has a schema
  // chain that `clean` would orphan; memory-only envs carry no risk.
  return Object.entries(manifest.environments)
    .filter(([, env]) => env.needsSqlserver)
    .map(([name]) => name)
    .sort();
}

async function pathExists(p: string): Promise<boolean> {
  try {
    await stat(p);
    return true;
  } catch (err) {
    if (isNotFound(err)) return false;
    throw err;
  }
}

function isNotFound(err: unknown): boolean {
  return (
    typeof err === 'object' &&
    err !== null &&
    'code' in err &&
    (err as { code: unknown }).code === 'ENOENT'
  );
}
