import { cleanProject, planClean } from 'archascode-core';

/**
 * IO surface for `clean`, injectable so tests drive confirmation without a
 * real TTY. Mirrors `runDeploy`'s IO-injection shape.
 */
export interface CleanIO {
  stdout: (text: string) => void;
  stderr: (text: string) => void;
  /** Ask the user to confirm the deletion. Resolves true to proceed. */
  confirm: (prompt: string) => Promise<boolean>;
}

export interface CleanInput {
  outDir: string;
  /** Skip the confirmation prompt (`--yes`). */
  assumeYes: boolean;
  /** Emit a machine-readable summary instead of human text (`--json`). */
  json: boolean;
  /**
   * When true, performs a total reset back to "nothing but architecture.yml":
   * deletes spec/locked/ (hand-owned bodies + migrations) in addition to the
   * regenerable surface. Use only to rebuild from zero (e.g. a corrupted
   * migration chain). Destructiveness is explicit and named — `--hard`.
   *
   * When false (default), the safe partition: resets only the regenerable
   * surface; spec/locked/ (bodies + migrations + ledger) kept.
   * ADR 062 D2.
   */
  hard?: boolean;
}

export type CleanCliOutcome =
  | { ok: true; removed: string[]; warnings: string[] }
  | { ok: false; reason: 'aborted' };

/**
 * Plan → warn → confirm → execute. Returns the outcome (also emitted to
 * stdout when `json`). Aborting at the prompt is a clean no-op, not an
 * error: exit 0 in human mode (the user chose not to), and the CLI maps
 * the `aborted` outcome to a non-zero code only in `--json` callers that
 * want to branch on it.
 */
export async function runClean(
  input: CleanInput,
  io: CleanIO,
): Promise<CleanCliOutcome> {
  const plan = await planClean({ outDir: input.outDir, hard: input.hard ?? false });

  if (plan.targets.length === 0) {
    if (input.json) {
      io.stdout(JSON.stringify({ ok: true, removed: [], warnings: plan.warnings }) + '\n');
    } else {
      io.stderr('nothing to clean — no render output found.\n');
    }
    return { ok: true, removed: [], warnings: plan.warnings };
  }

  if (!input.json) {
    io.stderr('clean will delete:\n');
    for (const t of plan.targets) io.stderr(`  - ${t}\n`);
    if (plan.warnings.length > 0) {
      io.stderr('\nwarnings:\n');
      for (const w of plan.warnings) io.stderr(`  ! ${w}\n`);
    }
    if (input.hard ?? false) {
      io.stderr(
        '\n--hard: deletes the whole render surface incl. spec/locked/ + migrations.\n' +
          'spec/architecture.yml and positions.json are kept. git can recover the rest.\n',
      );
    } else {
      io.stderr(
        '\nresets the regenerable surface; spec/locked/ (hand-owned bodies + migrations)\n' +
          'and the lockfile are kept. spec/architecture.yml and positions.json are kept.\n',
      );
    }
  }

  if (!input.assumeYes) {
    const ok = await io.confirm('Delete the render output? [y/N] ');
    if (!ok) {
      if (input.json) {
        io.stdout(JSON.stringify({ ok: false, reason: 'aborted' }) + '\n');
      } else {
        io.stderr('aborted; nothing deleted.\n');
      }
      return { ok: false, reason: 'aborted' };
    }
  }

  const result = await cleanProject({ outDir: input.outDir, hard: input.hard ?? false });

  if (input.json) {
    io.stdout(
      JSON.stringify({ ok: true, removed: result.removed, warnings: plan.warnings }) + '\n',
    );
  } else {
    io.stdout(`cleaned ${result.removed.length} target(s)\n`);
  }
  return { ok: true, removed: result.removed, warnings: plan.warnings };
}
